script:
import * as THREE from "https://esm.sh/three@0.170.0";

const root = element.matches("[data-ring]") ? element.parentElement : element;
const host = root.querySelector("[data-ring]");
const WORD = (host.dataset.word || "Worldwide").split("");
const CFG = {
  fromDeg: 102, toDeg: -295, introMs: 4500, introEase: [0.2, 0.9, 0.3, 0.986],
  ambientMs: 150000, scrollDegPerPx: 0.12, repulse: 2.5,
  pointerXDeg: 18, pointerDamping: 8,
  wordStaggerMs: 600, letterStaggerMs: 55, slideMs: 650, wipeMs: 300, sweepDeg: 14,
  tiltDeg: 18, radius: 45, letterRatio: 0.35, copies: 3, tracking: -0.08,
  radiusVmin: 37, topVmin: 9.2,
};
const G = Math.PI / 180;

function bezier(x1, y1, x2, y2) {
  const cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx;
  const cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
  const sx = t => ((ax * t + bx) * t + cx) * t, sy = t => ((ay * t + by) * t + cy) * t;
  const dx = t => (3 * ax * t + 2 * bx) * t + cx;
  return x => {
    if (x <= 0) return 0; if (x >= 1) return 1;
    let t = x;
    for (let i = 0; i < 8; i++) { const e = sx(t) - x; if (Math.abs(e) < 1e-6) break; const d = dx(t); if (Math.abs(d) < 1e-6) break; t -= e / d; }
    return sy(t);
  };
}
const introEase = bezier(...CFG.introEase);
const easeOut = bezier(0, 0, 0.58, 1);

const style = getComputedStyle(root);
const letterColor = new THREE.Color(style.color || "#fafafa");
const fontFamily = style.fontFamily || "system-ui, sans-serif";
const reduced = matchMedia("(prefers-reduced-motion: reduce)");

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setClearColor(0x000000, 0);
Object.assign(renderer.domElement.style, { position: "absolute", inset: "0", width: "100%", height: "100%", display: "block" });
host.appendChild(renderer.domElement);

const scene = new THREE.Scene();
const DIST = CFG.radius * 13.5;
const camera = new THREE.PerspectiveCamera(12, 1, 1, DIST * 4);
camera.position.set(0, 0, DIST);

const tilt = new THREE.Group();
const spin = new THREE.Group();
tilt.rotation.x = CFG.tiltDeg * G;
tilt.add(spin);
scene.add(tilt);

// glyph textures, drawn once per character
const FONT_PX = 256;
const em = CFG.radius * CFG.letterRatio;
const glyphs = new Map();
function glyph(ch) {
  if (glyphs.has(ch)) return glyphs.get(ch);
  const c = document.createElement("canvas");
  const ctx = c.getContext("2d");
  const font = `500 ${FONT_PX}px ${fontFamily}`;
  ctx.font = font;
  const m = ctx.measureText(ch);
  const asc = m.fontBoundingBoxAscent ?? FONT_PX * 0.98, desc = m.fontBoundingBoxDescent ?? FONT_PX * 0.26;
  const pad = 24;
  c.width = Math.ceil(m.width + pad * 2); c.height = Math.ceil(asc + desc + pad * 2);
  ctx.font = font; ctx.fillStyle = "#fff"; ctx.textBaseline = "alphabetic";
  ctx.fillText(ch, pad, pad + asc);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace; tex.anisotropy = 4;
  const g = { tex, advance: m.width / FONT_PX, w: c.width / FONT_PX * em, h: c.height / FONT_PX * em };
  glyphs.set(ch, g);
  return g;
}

const pointer = { ndc: new THREE.Vector2(9, 9), vel: new THREE.Vector2(), last: null, active: false, tiltX: 0 };
const shared = {
  uPointer: { value: pointer.ndc }, uVel: { value: pointer.vel },
  uInfluence: { value: CFG.repulse }, uAspect: { value: 1 },
};

const vert = `
uniform vec2 uPointer; uniform vec2 uVel; uniform float uInfluence; uniform float uAspect;
varying vec2 vUv;
void main() {
  vUv = uv;
  vec4 clip = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  vec2 d = clip.xy / clip.w - uPointer; d.x *= uAspect;
  float f = exp(-dot(d, d) / 0.05);
  clip.xy += uVel * uInfluence * 0.5 * f * clip.w;
  gl_Position = clip;
}`;
const frag = `
uniform sampler2D map; uniform vec3 uColor; uniform float uReveal; uniform float uOpacity;
varying vec2 vUv;
void main() {
  if (vUv.x > uReveal) discard;
  float a = texture2D(map, vUv).a * uOpacity;
  if (a < 0.003) discard;
  gl_FragColor = vec4(uColor, a);
}`;

const letters = [];
const all = [];
for (let w = 0; w < CFG.copies; w++) WORD.forEach((ch, i) => all.push({ ch, wordIndex: w, letterIndex: i }));
const widthsDeg = all.map(({ ch }) => (glyph(ch).advance + CFG.tracking) * CFG.letterRatio * (180 / Math.PI));
const gap = (360 - widthsDeg.reduce((a, b) => a + b, 0)) / CFG.copies;
let cursor = gap / 2, k = 0;
for (let w = 0; w < CFG.copies; w++) {
  for (let i = 0; i < WORD.length; i++, k++) {
    const g = glyph(all[k].ch);
    const rest = cursor + widthsDeg[k] / 2;
    cursor += widthsDeg[k];
    const mat = new THREE.ShaderMaterial({
      vertexShader: vert, fragmentShader: frag, transparent: true, depthWrite: false, side: THREE.DoubleSide,
      uniforms: { ...shared, map: { value: g.tex }, uColor: { value: letterColor }, uReveal: { value: 0 }, uOpacity: { value: 1 } },
    });
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(g.w, g.h, 12, 12), mat);
    mesh.position.z = CFG.radius;
    const holder = new THREE.Group();
    holder.add(mesh);
    holder.rotation.y = (rest - CFG.sweepDeg) * G;
    spin.add(holder);
    letters.push({ holder, mat, rest, ...all[k] });
  }
  cursor += gap;
}

let viewH = 1, W = 1, H = 1;
function resize() {
  const r = host.getBoundingClientRect();
  W = Math.max(1, r.width); H = Math.max(1, r.height);
  renderer.setSize(W, H, false);
  camera.aspect = W / H;
  const vmin = Math.min(W, H) / 100;
  // ring diameter on screen = 2 * radiusVmin; world diameter = 2 * radius
  viewH = (2 * CFG.radius) * H / (2 * CFG.radiusVmin * vmin);
  camera.fov = 2 * Math.atan(viewH / 2 / DIST) / G;
  camera.updateProjectionMatrix();
  const centerPx = (CFG.topVmin + CFG.radiusVmin) * vmin;
  tilt.position.y = (H / 2 - centerPx) * viewH / H;
  shared.uAspect.value = W / H;
}
new ResizeObserver(resize).observe(host);
resize();

let scrollSpin = 0;
root.addEventListener("wheel", e => { scrollSpin -= Math.max(-180, Math.min(180, e.deltaY)) * CFG.scrollDegPerPx; }, { passive: true });
let lastScrollY = window.scrollY;
addEventListener("scroll", () => { const y = window.scrollY; scrollSpin -= Math.max(-180, Math.min(180, y - lastScrollY)) * CFG.scrollDegPerPx; lastScrollY = y; }, { passive: true });

function onMove(e) {
  const r = host.getBoundingClientRect();
  const x = ((e.clientX - r.left) / r.width) * 2 - 1, y = -(((e.clientY - r.top) / r.height) * 2 - 1);
  if (pointer.last) pointer.vel.set(pointer.vel.x + (x - pointer.last.x), pointer.vel.y + (y - pointer.last.y));
  pointer.last = { x, y };
  pointer.ndc.set(x, y);
  pointer.active = true;
}
root.addEventListener("pointermove", onMove);
root.addEventListener("pointerleave", () => { pointer.active = false; pointer.last = null; });

let visible = true;
new IntersectionObserver(([en]) => { visible = en.isIntersecting; }, { threshold: 0 }).observe(host);

const clock = new THREE.Clock();
let start = null;
function ringAngle(t) {
  if (t <= 0) return CFG.fromDeg;
  if (t < CFG.introMs) return CFG.fromDeg + (CFG.toDeg - CFG.fromDeg) * introEase(t / CFG.introMs);
  return CFG.toDeg - 360 * ((t - CFG.introMs) / CFG.ambientMs);
}

function frame() {
  requestAnimationFrame(frame);
  const dt = Math.min(clock.getDelta(), 0.1);
  if (!visible) return;
  const now = performance.now();
  if (start === null) start = now;
  const t = now - start;
  const calm = reduced.matches;

  const target = pointer.active && !calm ? pointer.ndc.x * CFG.pointerXDeg : 0;
  pointer.tiltX += (target - pointer.tiltX) * (1 - Math.exp(-CFG.pointerDamping * dt));
  pointer.vel.multiplyScalar(Math.exp(-6 * dt));
  shared.uInfluence.value = calm ? 0 : CFG.repulse;

  if (calm) {
    const fade = easeOut(Math.min(t / 600, 1));
    spin.rotation.y = (CFG.toDeg + scrollSpin * 0.1) * G;
    tilt.rotation.x = CFG.tiltDeg * G;
    for (const l of letters) { l.mat.uniforms.uOpacity.value = fade; l.mat.uniforms.uReveal.value = 1; l.holder.rotation.y = l.rest * G; }
  } else {
    spin.rotation.y = (ringAngle(t) + scrollSpin + pointer.tiltX) * G;
    for (const l of letters) {
      const wStart = l.wordIndex * CFG.wordStaggerMs;
      const d = t - wStart;
      const slide = d <= 0 ? -CFG.sweepDeg : d < CFG.slideMs ? -CFG.sweepDeg * (1 - easeOut(d / CFG.slideMs)) : 0;
      l.holder.rotation.y = (l.rest + slide) * G;
      const p = t - (wStart + l.letterIndex * CFG.letterStaggerMs);
      l.mat.uniforms.uOpacity.value = 1;
      l.mat.uniforms.uReveal.value = p <= 0 ? 0 : p < CFG.wipeMs ? easeOut(p / CFG.wipeMs) : 1;
    }
  }
  renderer.render(scene, camera);
}
requestAnimationFrame(frame);
